  `suggested_budget_max` int DEFAULT NULL,
  `suggested_budget_min` int DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `tpo` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK3c9w1lipqdutm65a9inevwfp0` (`user_id`),
