CREATE TABLE `rooms` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `expires_at` datetime(6) NOT NULL,
  `finished_at` datetime(6) DEFAULT NULL,
  `idempotency_key` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `max_participants` int NOT NULL,
  `recommendation_version` bigint NOT NULL,
  `room_code` varchar(6) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` bigint NOT NULL,
  `confirmed_try_on_job_id` bigint DEFAULT NULL,
  `host_user_id` bigint NOT NULL,
  `recommendation_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rooms_room_code` (`room_code`),
  UNIQUE KEY `uk_rooms_host_idempotency_key` (`host_user_id`,`idempotency_key`),
  KEY `FK195frkt9pdyv1tcfpatfgubam` (`confirmed_try_on_job_id`),
  KEY `FK2ydvpn08eq2d66ttp94lqgu9e` (`recommendation_id`),
  CONSTRAINT `FK195frkt9pdyv1tcfpatfgubam` FOREIGN KEY (`confirmed_try_on_job_id`) REFERENCES `try_on_jobs` (`id`),
  CONSTRAINT `FK2ydvpn08eq2d66ttp94lqgu9e` FOREIGN KEY (`recommendation_id`) REFERENCES `recommendations` (`id`),
  CONSTRAINT `FKa6ersec270glcievv4gt6xtl1` FOREIGN KEY (`host_user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=126 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
